# handling subscription and notifications about iperf intermediate reports
from six.moves.queue import Queue, Empty
from ...exceptions import UeProcedureError
from . import host


def _no_observer(data_record=None, report=None):
    pass


class IperfPublisher:
    def __init__(self, iperf_direction, port, ue_ip, app_server_ip, iperf_client, iperf_server, logger):
        """
        Handling subscription and notifications about iperf intermediate reports

        :param iperf_direction: ul / dl / simultaneous_ul_dl
        :param port: iperf port
        :param ue_ip: IP of UE
        :param app_server_ip: IP of AppSvr
        :param iperf_client: moler command object
        :param iperf_server: moler command object
        :param logger: logger to use
        """
        self.direction = iperf_direction
        self.port = port
        self.ue_ip = ue_ip
        self.app_server_ip = app_server_ip
        self.iperf_client = iperf_client
        self.iperf_server = iperf_server
        self.logger = logger
        self._data_transfer_subscriber = {'ul': _no_observer, 'dl': _no_observer}
        self.iperf_stats_queue = Queue()

    def subscribe(self, subscriber, direction):
        """
        Subscribe for notifications about iperf statistic (at given direction) as it comes.

        NOTE: only one subscriber per direction at a time, to change subscriber you need to unsubscribe first

        Anytime we find iperf server statistics line like:
        [  3]  2.0- 3.0 sec   612 KBytes  5010 Kbits/sec   0.022 ms    0/  426 (0%)
        such line is parsed and published to subscriber

        Subscriber must be function or method with following signature (name doesn't matter):

            def iperf_observer(data_record=None, report=None):
                '''
                :param data_record: dictionary with intermediate iperf statistics
                :param report: dictionary with final iperf statistics
                '''
                ...

        Either data_record is published or report.
        Report is published on last line of iperf statistics summarizing stats for whole period:
        [904]   0.0-10.0 sec   11.8 MBytes   9.86 Mbits/sec   2.618 ms   9/ 8409  (0.11%)

        :param subscriber: function to be called to notify about data.
        """
        assert (direction == 'ul') or (direction == 'dl')
        if self._data_transfer_subscriber[direction] != _no_observer:
            return
        if (self.direction != 'simultaneous_ul_dl') and (direction != self.direction):
            raise UeProcedureError(f"Can't subscribe for '{direction}' statistics on '{self.direction}' only traffic")
        self._data_transfer_subscriber[direction] = subscriber
        if direction == 'dl':  # we trust only server for its reports (what traffic reached server)
            if self.direction == 'dl':
                iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_server)
                iperf_cmd.subscribe(self._forward_downlink_stats2subscriber)  # iperf_server is at UE-PC
            else:  # simultaneous_ul_dl
                iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_client)
                iperf_cmd.subscribe(self._forward_downlink_stats2subscriber)  # iperf_client is at UE-PC
        else:
            iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_server)
            iperf_cmd.subscribe(self._forward_uplink_stats2subscriber)

    def unsubscribe(self, direction):
        """Unsubscribe function/method subscribed via subscribe()"""
        if self._data_transfer_subscriber[direction] is _no_observer:
            return
        self._data_transfer_subscriber[direction] = _no_observer
        if direction == 'dl':
            if self.direction == 'dl':
                iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_server)
                iperf_cmd.unsubscribe(self._forward_downlink_stats2subscriber)
            else:  # simultaneous_ul_dl
                iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_client)
                iperf_cmd.unsubscribe(self._forward_downlink_stats2subscriber)
        else:
            iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_server)
            iperf_cmd.unsubscribe(self._forward_uplink_stats2subscriber)

    def _forward_downlink_stats2subscriber(self, from_client, to_server, data_record=None, report=None):
        if self._data_transfer_subscriber['dl'] is _no_observer:
            return
        ue_pc_endpoint = f"{self.port}@{self.ue_ip}"
        if to_server == ue_pc_endpoint:
            observer = self._data_transfer_subscriber['dl']
            observer(data_record=data_record, report=report)

    def _forward_uplink_stats2subscriber(self, from_client, to_server, data_record=None, report=None):
        if self._data_transfer_subscriber['ul'] is _no_observer:
            return
        app_svr_endpoint = f"{self.port}@{self.app_server_ip}"
        if to_server == app_svr_endpoint:
            observer = self._data_transfer_subscriber['ul']
            observer(data_record=data_record, report=report)

    def _forward_downlink_stats2queue(self, data_record=None, report=None):
        # at iperf finish report is not None and data_record is None
        # data_record == None means "end of statistics"
        # TODO: shouldn't we also record/publish time when statistics comes to have good diagrams?
        # TODO: where to collect time: API simplicity vs. data accuracy
        self.iperf_stats_queue.put(('dl', data_record))

    def _forward_uplink_stats2queue(self, data_record=None, report=None):
        self.iperf_stats_queue.put(('ul', data_record))

    def _subscribe_queue_forwarders(self, direction):
        end_of_stats = {'ul': True, 'dl': True}

        if (direction == 'ul') or (direction == 'simultaneous_ul_dl'):
            self.subscribe(self._forward_uplink_stats2queue, direction='ul')
            end_of_stats['ul'] = False
        if (direction == 'dl') or (direction == 'simultaneous_ul_dl'):
            self.subscribe(self._forward_downlink_stats2queue, direction='dl')
            end_of_stats['dl'] = False
        return end_of_stats

    def statistics_iterator(self, direction, next_statistics_timeout=10):  # noqa: C901
        """
        Generator function iterating over iperf data transfer statistics

        Iterator returns pairs (direction, statistics_for_that_direction)

        :param direction: which direction to iterate on (ul/dl/simultaneous_ul_dl)
        :param next_statistics_timeout: Max timeout to await for next stats. If exceeded we break iteration.

        :return: generator object (iterator) over incoming (direction, stats) of data_transfer
        """
        # iperf observer is not within main thread so, we need queue
        end_of_stats = self._subscribe_queue_forwarders(direction)

        try:
            while True:
                direction_of_stats, stats = self.iperf_stats_queue.get(block=True, timeout=next_statistics_timeout)
                if stats is None:  # means end of statistics records
                    end_of_stats[direction_of_stats] = True
                if end_of_stats['ul'] and end_of_stats['dl']:
                    break
                if stats:
                    yield direction_of_stats, stats
        except Empty:
            info = f"No iperf statistics came within {next_statistics_timeout} sec timeout"
            self.logger.warning(info)
        finally:
            self.unsubscribe('ul')
            self.unsubscribe('dl')
